func TestCustomersCSVNeutralisesFormulas(t *testing.T) {
	srv, st := newServer(t)
	st.CreateCustomer("acc_acme", `=SUM(A1,"x")`, "+1@example.com", store.PlanFree, time.Now())
	st.CreateCustomer("acc_acme", "-Bob", "@corp.example.com", store.PlanFree, time.Now())
